WITH `srfuzz_n1` AS (SELECT `t`.`id`, `t`.`info` FROM (VALUES(1, named_struct('name', 'Alice', 'score', 95)), (2, named_struct('name', 'Bob', 'score', 88)), (3, named_struct('name', 'Charlie', 'score', 92)), (4, named_struct('name', 'David', 'score', 85)), (5, named_struct('name', 'Eve', 'score', 90))) t(id,info)) SELECT `t`.`id`, `t`.`info` FROM `srfuzz_n1` AS t ORDER BY `t`.`info` ASC  LIMIT 3;
