SELECT `t`.`id`, `t`.`info`, `srfuzz_n1`.`e` FROM (SELECT `t`.`id`, `t`.`info` FROM (VALUES(1, named_struct('name', 'Alice', 'score', 95)), (2, named_struct('name', 'Bob', 'score', 88)), (3, named_struct('name', 'Charlie', 'score', 92)), (4, named_struct('name', 'David', 'score', 85)), (5, named_struct('name', 'Eve', 'score', 90))) t(id,info)) `t` , LATERAL generate_series(1,3,1) srfuzz_n1(`e`)  ORDER BY `t`.`info` ASC  LIMIT 3;
